<?php
namespace App\Http\Controllers;use App\Models\{Order,Product,Review};use Illuminate\Http\Request;class AccountController extends Controller{public function index(Request $r){return view('account.index',['orders'=>$r->user()->orders()->latest()->take(5)->get()]);}public function orders(Request $r){return view('account.orders',['orders'=>$r->user()->orders()->latest()->paginate(10)]);}public function order(Request $r,Order $order){abort_unless($order->user_id===$r->user()->id,404);$order->load('items','payment');return view('account.order',compact('order'));}public function favorite(Request $r,Product $product){$r->user()->favorites()->toggle($product->id);return back()->with('success','Favoris mis à jour.');}public function review(Request $r,Product $product){$d=$r->validate(['rating'=>'required|integer|min:1|max:5','comment'=>'nullable|string|max:1000']);Review::updateOrCreate(['user_id'=>$r->user()->id,'product_id'=>$product->id],$d+['is_approved'=>false]);return back()->with('success','Avis envoyé pour validation.');}}
